  OBOL.playbookData = {"ad-recon":{"name":"ad-recon","title":"AD Initial Recon","description":"The opening evidence sweep for a domain-joined target: nmap discovery through anonymous AD enumeration. Each step runs through the same scope-enforced runner and parser as `obol run`.","steps":[{"label":"Fast TCP open-port discovery","action_id":"nmap-fast-open-ports","note":"All TCP ports at a high rate; establishes the live host and open ports."},{"label":"Targeted service and default-script scan","action_id":"nmap-version-scripts","note":"Fingerprints the discovered ports so AD service moves unlock. Runs after step 1 fills the port list."},{"label":"Identify the domain controller and domain","action_id":"ad-dc-identify","note":"NetExec LDAP smoke test: DC candidate, domain name, and base DN."},{"label":"Anonymous LDAP enumeration","action_id":"ad-anon-ldap-enum","note":"Unauthenticated bind for the domain user list."},{"label":"SMB / RID user enumeration","action_id":"ad-user-enum","require_approval":true,"note":"Guest RID brute-force — the noisiest recon step; use when anonymous LDAP is thin."}],"phase":"recon"},"domain-persistence":{"name":"domain-persistence","title":"Establish Domain Persistence (defense-in-depth)","description":"Once you own the domain (a krbtgt hash, a replicated NTDS dump, or Domain-Admin rights), lay down SEVERAL INDEPENDENT persistence mechanisms so cleaning up any one does not evict you. Each step is a separate fact-gated pack action producing its own persistence.domain fact and runs through the same scope-enforced runner as `obol run`; unmet steps (e.g. no krbtgt hash yet) are skipped, and every step is approval-gated because it modifies domain infrastructure — obol crafts and runs on approval, never silently. Post-exploitation / OSEP-tier: opt in deliberately (never needed to pass an OSCP exam).","steps":[{"label":"Golden ticket (forge a TGT from the krbtgt key)","action_id":"golden-ticket","require_approval":true,"note":"The krbtgt-key forgery — any user, any group, offline. The broadest persistence; survives every password reset except krbtgt (twice)."},{"label":"Diamond ticket (re-sign a real DC-issued TGT)","action_id":"diamond-ticket","require_approval":true,"note":"Stealthier than golden — modifies a legitimately-issued ticket rather than forging one, so it blends with real Kerberos traffic. Independent of the golden path above."},{"label":"WSUS abuse (push a signed update as SYSTEM)","action_id":"wsus-abuse","require_approval":true,"note":"A patch-infrastructure foothold — independent of Kerberos entirely, so it survives a krbtgt double-reset that kills the ticket mechanisms."},{"label":"DnsAdmins ServerLevelPluginDll (DC SYSTEM via a DLL)","action_id":"dnsadmins-abuse","require_approval":true,"note":"Load a plugin DLL into the DNS service running as SYSTEM on the DC — a separate write-privesc persistence lever, gated on a control path over the DC/DnsAdmins."},{"label":"SID-history injection (cross-forest / hidden DA membership)","action_id":"sid-history-abuse","require_approval":true,"note":"Inject a high-privilege SID into an account you control — persistence that does not depend on holding krbtgt, and reaches across a trust when one exists."}],"phase":"loot"},"prepare-reverse-shell":{"name":"prepare-reverse-shell","title":"Prepare a Reverse Shell","description":"Stand up everything needed to catch a shell: a listener, a Linux and a Windows payload crafted for it, and the PTY-upgrade recipe for once it lands. obol never fires the payload — it crafts and stages; you trigger it. Each step runs through the same scope-enforced runner as `obol run`.","steps":[{"label":"Start a reverse-shell listener","action_id":"shell-listener","note":"Opens the catcher on an operator/callback port; the crafted payloads point back at it."},{"label":"Craft a Linux reverse-shell payload","action_id":"shell-revshell-linux","note":"Renders the one-liner (bash/nc/etc.) targeting the listener — copy it to run on the box; never auto-fired."},{"label":"Craft a Windows reverse-shell payload","action_id":"shell-revshell-windows","note":"The Windows equivalent (PowerShell/nc.exe). Skip the OS you don't need — per-step, operator's choice."},{"label":"Upgrade a dumb shell to a full PTY","action_id":"shell-pty-upgrade","note":"The recipe to turn the caught shell into an interactive TTY (job control, vim, sudo) — for after it lands."}],"phase":"access"},"tunnel-and-sweep":{"name":"tunnel-and-sweep","title":"Tunnel and Sweep a New Segment","description":"Stand up a pivot from a proven foothold and enumerate the segment it exposes. Pick ONE tunnel method (the applicable one is ready; the rest skip or wait for approval), then scan an internal host through the proxy. A proven tunnel auto-extends scope to the exposed subnet — the hard gate stays enforced, never bypassed. Each step runs through the one scope-enforced runner.","steps":[{"label":"Pivot: SSH dynamic port-forward (SOCKS)","action_id":"pivot-ssh-dynamic","require_approval":true,"note":"The simplest pivot when you have SSH creds on the foothold — a SOCKS proxy over the SSH session."},{"label":"Pivot: sshuttle transparent tunnel (alternative)","action_id":"pivot-sshuttle","require_approval":true,"note":"A transparent, route-based alternative over SSH — no per-tool proxychains needed."},{"label":"Pivot: Chisel reverse SOCKS (no-SSH alternative)","action_id":"pivot-chisel-socks","require_approval":true,"note":"When there's no SSH: stage chisel and open a reverse SOCKS tunnel back through the listener."},{"label":"Scan an internal host through the proxy","action_id":"pivot-scan-through","note":"Once a tunnel is up (scope auto-extended to the exposed subnet), enumerate a host on the far side."}],"phase":"access"},"web-recon":{"name":"web-recon","title":"Web Initial Recon","description":"The opening evidence sweep for an HTTP target: content discovery, nikto, and virtual-host fuzzing. Unlocks once nmap has proven an HTTP port. Each step runs through the same scope-enforced runner and parser as `obol run`.","steps":[{"label":"Content discovery","action_id":"content-discovery","note":"Fuzz paths for the unlinked surface (admin panels, .git, backups, /api) — maps discovered content."},{"label":"Nikto scan","action_id":"nikto-scan","note":"Baseline server/app misconfiguration and interesting-file leads (candidates to verify, not confirmed vulns)."},{"label":"Virtual-host discovery","action_id":"vhost-discovery","require_approval":true,"note":"Subdomain/vhost fuzzing — noisier, and needs a known domain (set one with --set domain=example.com if nmap did not reveal it)."}],"phase":"recon"}};
